import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as l,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const A=JSON.parse('{"title":"Hello Agents（DataWhale）","description":"DataWhale 开源 Agent 教程的学习笔记：Agent 基础组件、框架、工具设计与 Memory 管理策略的入门路线。","frontmatter":{"title":"Hello Agents（DataWhale）","description":"DataWhale 开源 Agent 教程的学习笔记：Agent 基础组件、框架、工具设计与 Memory 管理策略的入门路线。","domain":"tech","tags":["tech","course-notes","legacy","agent"],"navOrder":80,"topicId":"course-notes-hello-agents","layer":"appendix","status":"legacy","nodeType":"resource","owner":"learn-ai","lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"zh/tech/appendices/course-notes/hello-agents-datwhale.md","filePath":"zh/tech/appendices/course-notes/hello-agents-datwhale.md","lastUpdated":1791173509000}'),n={name:"zh/tech/appendices/course-notes/hello-agents-datwhale.md"};function r(s,e,h,i,g,c){return l(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="hello-agents-datawhale" tabindex="-1">Hello Agents（DataWhale） <a class="header-anchor" href="#hello-agents-datawhale" aria-label="Permalink to &quot;Hello Agents（DataWhale）&quot;">​</a></h1><blockquote><p>来源：<a href="https://datawhalechina.github.io/hello-agents/#/" target="_blank" rel="noreferrer">DataWhale Hello Agents</a>，开源 Agent 学习教程</p></blockquote><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>Hello Agents 是 DataWhale 出品的 Agent 教程，从零开始覆盖 Agent 概念、架构与实践：基础概念 → 框架学习 → 工具设计 → 项目实战。</p><h2 id="核心内容模块" tabindex="-1">核心内容模块 <a class="header-anchor" href="#核心内容模块" aria-label="Permalink to &quot;核心内容模块&quot;">​</a></h2><p><strong>1. Agent 基础</strong>：Agent 是利用大语言模型进行推理、规划和执行动作的系统。关键组件——Planning（任务分解与规划）、Memory（记忆管理）、Tools（工具调用）、Action（执行动作）。</p><p><strong>2. 主流框架</strong>：LangChain、AutoGPT、LlamaIndex 等开源框架。</p><p><strong>3. 工具设计</strong>：工具是 Agent 与外部世界交互的桥梁。好的工具设计需要清晰描述、合理参数、明确返回值格式。</p><p><strong>4. Memory 管理</strong>：</p><ul><li>短窗口记忆：直接放入上下文</li><li>长期记忆：向量数据库或文件存储</li><li>混合策略：分层记忆管理</li></ul><p><strong>5. 项目实战</strong>：理论与实践结合。</p><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ol><li>先理解概念：Agent 核心是 LLM + 工具 + 规划能力</li><li>多动手实践：看源码、改代码、做实验</li><li>关注工具设计：工具质量直接影响 Agent 效果</li><li>理解 Memory：上下文管理是 Agent 工程的关键难点</li></ol><h2 id="与主线的关系" tabindex="-1">与主线的关系 <a class="header-anchor" href="#与主线的关系" aria-label="Permalink to &quot;与主线的关系&quot;">​</a></h2><p>本笔记的组件分解与 Memory 策略已展开为主线 <a href="/zh/tech/06-agent-systems/agent-runtime.html">Agent 运行时</a>与 <a href="/zh/tech/06-agent-systems/state-memory.html">Agent 状态与记忆</a>；本页保留为课程出处与入门路线索引。</p><blockquote><p>注：本笔记基于 Hello Agents 教程大纲整理，具体内容请参考<a href="https://datawhalechina.github.io/hello-agents/#/" target="_blank" rel="noreferrer">官方教程</a>。</p></blockquote>',16)])])}const _=a(n,[["render",r]]);export{A as __pageData,_ as default};
